const notificationInbox=createNotificationInbox({onImport:async(batch,context)=>{if(!credential||!live||live.status!=='live'||context.identity!==credential.storeId+':staff:'+credential.memberId||live.data?.member.id!==credential.memberId)throw Error('noAccess');const result=await teamRequest(credential.storeId,'staff/'+credential.memberId,'PATCH',{action:'notificationImport',data:{ids:batch.map(n=>n.amendmentId)}},credential.token);live?.refresh();return result;},onOpen:n=>{staffNotices=staffNotices.filter(x=>x.key!==n.key);tab=n.kind==='orders'?'ordersView':'bookingsView';queueFilter='all';render();document.querySelector('[data-record-id="'+CSS.escape(n.id)+'"]')?.focus({preventScroll:false});}});
