function syncStaffNotices(v){const memberRole=v.member.role;if(!['floor','kitchen'].includes(memberRole)){staffNotices=[];staffCounterTracker=null;staffCounterRole=null;return;}if(!staffCounterTracker||staffCounterRole!==memberRole){staffCounterTracker=createCounterTracker(memberRole);staffCounterRole=memberRole;staffNotices=[];}staffNotices=staffNotices.filter(n=>!v.notificationReads?.includes(n.key)&&currentCounterNotice(n,v,memberRole));for(const n of staffCounterTracker.scan(v)){if(v.notificationReads?.includes(n.key))continue;staffNotices=staffNotices.filter(old=>old.key!==n.key);staffNotices.unshift(n);}staffNotices=staffNotices.slice(0,8);}
