document.addEventListener('click',e=>{const b=e.target.closest('[data-staff-open-notice],[data-staff-dismiss-notice]');if(!b)return;const key=b.dataset.staffOpenNotice||b.dataset.staffDismissNotice,n=staffNotices.find(x=>x.key===key);staffNotices=staffNotices.filter(x=>x.key!==key);if(n&&b.dataset.staffOpenNotice){notificationInbox.mark(n.key);tab=n.kind==='orders'?'ordersView':'bookingsView';queueFilter='all';render();document.querySelector('[data-record-id="'+CSS.escape(n.id)+'"]')?.focus({preventScroll:false});}else renderStaffAlert(live?.data);});
