async function act(action,data){if(live?.busy)return;root.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(role)teamChange(s=>staffAction(s,id,action,data),key);else if(live)await live.mutate('', 'PATCH',{action,data});else throw Error('credentialsMissing');if(action==='amend')reviewDrafts.delete(data.id);notice=action==='amend'?amendmentCopy(lang,data.approve?'changed':'rejected'):t(action==='order'?data.next:action==='booking'?'bookingConfirmed':'saved');}catch(e){notice=t(e.message);}render();}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-live-retry')){live?.invalidate();return;}if(b.dataset.queue){queueFilter=b.dataset.queue;notice='';render();return;}if(b.dataset.tab){tab=b.dataset.tab;notice='';render();}if(b.hasAttribute('data-reset')&&role){localStorage.removeItem(key);notice='';render();}if(b.dataset.staffAmend)act('amend',{id:b.dataset.staffAmend,approve:b.dataset.approve==='true'});if(b.dataset.staffOrder)act('order',{id:b.dataset.staffOrder,next:b.dataset.next});if(b.dataset.staffBooking)act('booking',{id:b.dataset.staffBooking});if(b.dataset.staffMenu)act('menu',{id:b.dataset.staffMenu,available:b.dataset.available==='true'});});
root.addEventListener('submit',e=>{e.preventDefault();if(e.target.dataset.form==='staff-amend-reject'){const f=e.target;act('amend',{id:f.dataset.request,approve:false,reason:new FormData(f).get('reason'),...(f.elements.offer?.checked?{offer:f.dataset.type==='order'?{type:'order',itemId:f.elements.itemId.value,quantity:Number(f.elements.quantity.value)}:{type:'booking',date:f.elements.date.value,time:f.elements.time.value}}:{})});return;}if(e.target.id==='staff-settings')act('settings',{phone:new FormData(e.target).get('phone')});});
